package br.com.erp;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
class PayableTreasuryTest extends ApiTestSupport {
 String auth,account;UUID branch,supplier;
 @BeforeEach void fixture()throws Exception{
  auth=token(company);branch=db.queryForObject("SELECT id FROM branch WHERE tenant_id=?",UUID.class,tenant);
  supplier=UUID.fromString(postApi("/api/v1/suppliers",auth,Map.of("code","SUP","name","Fornecedor","taxIdentifier","","contactName","","email","","phone","","address","","notes",""),201).get("id").asText());
  account=createAccount(branch,"BANK");credit("200");
 }
 String createAccount(UUID branch,String code)throws Exception{return postApi("/api/v1/treasury/accounts",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"code",code,"name","Conta "+code,"kind","BANK"),201).get("id").asText();}
 void credit(String amount)throws Exception{postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"destinationId",account,"amount",amount,"note","Crédito de teste"),200);}
 JsonNode title(String ref)throws Exception{return postApi("/api/v1/payables",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"supplierId",supplier,"reference",ref,"document","","description","Título de teste","issuedOn","2020-01-01","dueOn","2020-02-01","amount","100"),201);}
 String path(JsonNode title){return "/api/v1/payables/"+title.get("id").asText();}
 Map<String,Object> payment(UUID id,String amount,String account){var input=new HashMap<String,Object>();input.put("paymentId",id);input.put("amount",amount);input.put("paidOn","2020-02-01");input.put("method","BANK_TRANSFER");input.put("reference","");input.put("note","Pagamento de teste");input.put("treasuryAccountId",account);return input;}
 Map<String,Object> reversal(UUID id){return Map.of("requestId",id,"note","Correção de teste");}
 void balance(String expected){assertEquals(0,new BigDecimal(expected).compareTo(db.queryForObject("SELECT balance FROM treasury_account WHERE tenant_id=? AND id=?",BigDecimal.class,tenant,UUID.fromString(account))));}
 long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE tenant_id=?",Long.class,tenant);}
 @Test void linkedPaymentAndReversalUpdateBothLedgersExactlyOnce()throws Exception{
  var title=title("ONE");UUID id=UUID.randomUUID(),reverse=UUID.randomUUID();var input=payment(id,"40",account);var paid=postApi(path(title)+"/payments",auth,input,200);balance("160");assertEquals(account,paid.get("treasuryAccountId").asText());assertFalse(paid.get("treasuryOperationId").isNull());assertEquals(paid,postApi(path(title)+"/payments",auth,payment(id,"40.00",account),200));
  String endpoint=path(title)+"/payments/"+id+"/reverse";var reversed=postApi(endpoint,auth,reversal(reverse),200);balance("200");assertFalse(reversed.get("treasuryReversalOperationId").isNull());assertEquals(reversed,postApi(endpoint,auth,reversal(reverse),200));assertEquals(reversed,postApi(path(title)+"/payments",auth,input,200));balance("200");assertEquals(3,count("treasury_operation"));assertEquals("OPEN",getApi(path(title),auth,200).get("status").asText());
  var entries=getApi("/api/v1/treasury/accounts/"+account+"/entries",auth,200).get("items");assertEquals("PAYABLE_REVERSAL",entries.get(0).get("origin").asText());assertEquals("PAYABLE_PAYMENT",entries.get(1).get("origin").asText());
 }
 @Test void insufficientBalanceRollsBackPaymentAndTitle()throws Exception{var t=title("ONE");String empty=createAccount(branch,"EMPTY");postApi(path(t)+"/payments",auth,payment(UUID.randomUUID(),"10",empty),409);assertEquals(0,count("payable_payment"));assertEquals(1,count("treasury_operation"));assertEquals("OPEN",getApi(path(t),auth,200).get("status").asText());balance("200");}
 @Test void accountCannotBeChangedOrOmittedOnReplay()throws Exception{var t=title("ONE");UUID id=UUID.randomUUID();postApi(path(t)+"/payments",auth,payment(id,"10",account),200);postApi(path(t)+"/payments",auth,payment(id,"10",null),409);String other=createAccount(branch,"OTHER");postApi(path(t)+"/payments",auth,payment(id,"10",other),409);balance("190");assertEquals(2,count("treasury_operation"));}
 @Test void externalPaymentRemainsCompatibleWithoutTreasuryPrivileges()throws Exception{var t=title("ONE");db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission LIKE 'treasury:%'",tenant);UUID id=UUID.randomUUID();var external=postApi(path(t)+"/payments",auth,payment(id,"20",null),200);assertTrue(external.get("treasuryOperationId").isNull());postApi(path(t)+"/payments/"+id+"/reverse",auth,reversal(UUID.randomUUID()),200);balance("200");assertEquals(1,count("treasury_operation"));postApi(path(t)+"/payments",auth,payment(UUID.randomUUID(),"10",account),403);}
 @Test void reversalRequiresTreasuryPermissionsAndAccountScope()throws Exception{var t=title("ONE");UUID id=UUID.randomUUID();postApi(path(t)+"/payments",auth,payment(id,"20",account),200);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='treasury:move'",tenant);postApi(path(t)+"/payments/"+id+"/reverse",auth,reversal(UUID.randomUUID()),403);balance("180");assertEquals("20.00",getApi(path(t),auth,200).get("paidAmount").asText());}
 @Test void accountInOtherBranchRequiresAccessOnPayAndReversal()throws Exception{
  var t=title("ONE");UUID other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","OTHER","name","Outra filial"),201).get("id").asText());String bank=createAccount(other,"OTHER");account=bank;credit("100");UUID id=UUID.randomUUID();postApi(path(t)+"/payments",auth,payment(id,"20",bank),200);
  UUID user=db.queryForObject("SELECT id FROM app_user WHERE tenant_id=?",UUID.class,tenant);db.update("UPDATE app_user SET all_branches=FALSE WHERE id=?",user);db.update("INSERT INTO user_branch_access(tenant_id,user_id,branch_id) VALUES(?,?,?)",tenant,user,branch);postApi(path(t)+"/payments",auth,payment(UUID.randomUUID(),"10",bank),404);postApi(path(t)+"/payments/"+id+"/reverse",auth,reversal(UUID.randomUUID()),404);balance("80");assertEquals(1,count("payable_payment"));
 }
 @Test void reusedReversalKeyRollsBackTreasuryCredit()throws Exception{var t=title("ONE");UUID a=UUID.randomUUID(),b=UUID.randomUUID(),r=UUID.randomUUID();postApi(path(t)+"/payments",auth,payment(a,"30",account),200);postApi(path(t)+"/payments",auth,payment(b,"40",account),200);postApi(path(t)+"/payments/"+a+"/reverse",auth,reversal(r),200);postApi(path(t)+"/payments/"+b+"/reverse",auth,reversal(r),409);balance("160");assertEquals(4,count("treasury_operation"));assertEquals("40.00",getApi(path(t),auth,200).get("paidAmount").asText());}
 @Test void overflowingReversalPreservesOriginalPayment()throws Exception{var t=title("ONE");UUID id=UUID.randomUUID();postApi(path(t)+"/payments",auth,payment(id,"100",account),200);credit("99999999999999899.99");postApi(path(t)+"/payments/"+id+"/reverse",auth,reversal(UUID.randomUUID()),409);balance("99999999999999999.99");assertEquals("PAID",getApi(path(t),auth,200).get("status").asText());assertEquals(3,count("treasury_operation"));}
 @Test void concurrentPaymentReplayDebitsOnce()throws Exception{var t=title("ONE");var p=payment(UUID.randomUUID(),"100",account);assertEquals(List.of(200,200),concurrent(path(t)+"/payments",p,path(t)+"/payments",p));balance("100");assertEquals(1,count("payable_payment"));assertEquals(2,count("treasury_operation"));}
 @Test void concurrentTitlesCannotSpendSameAccountBalance()throws Exception{var a=title("A");var b=title("B");postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"sourceId",account,"amount","100","note","Retirada de teste"),200);assertEquals(List.of(200,409),concurrent(path(a)+"/payments",payment(UUID.randomUUID(),"80",account),path(b)+"/payments",payment(UUID.randomUUID(),"80",account)));balance("20");assertEquals(1,count("payable_payment"));}
 @Test void concurrentPaymentAndManualWithdrawalCannotOverdraw()throws Exception{var t=title("ONE");postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"sourceId",account,"amount","100","note","Retirada de teste"),200);var manual=Map.of("requestId",UUID.randomUUID(),"sourceId",account,"amount","80","note","Retirada concorrente");assertEquals(List.of(200,409),concurrent(path(t)+"/payments",payment(UUID.randomUUID(),"80",account),"/api/v1/treasury/movements",manual));balance("20");assertEquals(3,count("treasury_operation"));}
 @Test void concurrentReversalRetriesCreditOnce()throws Exception{var t=title("ONE");UUID id=UUID.randomUUID();postApi(path(t)+"/payments",auth,payment(id,"100",account),200);var r=reversal(UUID.randomUUID());String endpoint=path(t)+"/payments/"+id+"/reverse";assertEquals(List.of(200,200),concurrent(endpoint,r,endpoint,r));balance("200");assertEquals(3,count("treasury_operation"));}
 @Test void foreignTenantAccountIsNotAccepted()throws Exception{var t=title("ONE");UUID other=provisioning.create("Outra","other-"+UUID.randomUUID(),"Admin","admin@example.com",password);UUID bank=UUID.randomUUID();db.update("INSERT INTO treasury_account(id,tenant_id,request_id,fingerprint,branch_id,code,name,kind,created_by) SELECT ?,?,?,'hash',b.id,'OTHER','Outra conta','BANK',u.id FROM branch b JOIN app_user u ON u.tenant_id=b.tenant_id WHERE b.tenant_id=?",bank,other,UUID.randomUUID(),other);postApi(path(t)+"/payments",auth,payment(UUID.randomUUID(),"10",bank.toString()),404);balance("200");assertEquals(0,count("payable_payment"));}
 List<Integer> concurrent(String p1,Object b1,String p2,Object b2)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var f1=pool.submit(()->{gate.await();return status(p1,b1);});var f2=pool.submit(()->{gate.await();return status(p2,b2);});gate.countDown();var result=new ArrayList<>(List.of(f1.get(30,TimeUnit.SECONDS),f2.get(30,TimeUnit.SECONDS)));Collections.sort(result);return result;}}
 int status(String path,Object body)throws Exception{return http.perform(post(path).header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(body))).andReturn().getResponse().getStatus();}
}
